     1	import type {ReasoningUIPart} from 'ai';
     2	import type {AgentMessage, TurnEvent} from '@/lib/agent/types';
     3	import * as stylex from '@stylexjs/stylex';
     4	import {ChatMessage, ChatMessageBubble} from '@astryxdesign/core/Chat';
     5	import {Collapsible} from '@astryxdesign/core/Collapsible';
     6	import {Markdown} from '@astryxdesign/core/Markdown';
     7	import {Text} from '@astryxdesign/core/Text';
     8	import {MODELS} from '@/lib/agent/models';
     9	import {ApprovalCard, type ApprovalDecision} from './ApprovalCard';
    10	import {Checkpoint} from './Checkpoint';
    11	import {DeniedCall} from './DeniedCall';
    12	import {DiffView} from './DiffView';
    13	import {ToolCall, type ToolPart} from './ToolCall';
    14	import {VerifyResult} from './VerifyResult';
    15	
    16	type Part = AgentMessage['parts'][number];
    17	
    18	type MessageProps = {
    19	  message: AgentMessage;
    20	  onApproval?(approvalId: string, approved: boolean): void;
    21	  onEvent?(event: TurnEvent): void;
    22	};
    23	
    24	const styles = stylex.create({
    25	  reasoning: {whiteSpace: 'pre-wrap'},
    26	  userText: {whiteSpace: 'pre-wrap'},
    27	});
    28	
    29	const isToolPart = (part: Part): part is ToolPart => part.type === 'dynamic-tool' || part.type.startsWith('tool-');
    30	
    31	function decisionOf(part: ToolPart): ApprovalDecision {
    32	  if (part.state === 'approval-requested') return 'pending';
    33	  if (part.state === 'output-denied' || (part.state === 'approval-responded' && !part.approval.approved)) return 'denied';
    34	  return 'approved';
    35	}
    36	
    37	function Reasoning({part}: {part: ReasoningUIPart}) {
    38	  const isStreaming = part.state === 'streaming';
    39	  return (
    40	    <Collapsible
    41	      defaultIsOpen={isStreaming}
    42	      trigger={
    43	        <Text type="supporting" color="secondary">
    44	          {isStreaming ? 'Thinking' : 'Thought'}
    45	        </Text>
    46	      }>
    47	      <Text type="supporting" color="secondary" xstyle={styles.reasoning}>
    48	        {part.text}
    49	      </Text>
    50	    </Collapsible>
    51	  );
    52	}
    53	
    54	export function Message({message, onApproval, onEvent}: MessageProps) {
    55	  if (message.role === 'user') {
    56	    const text = message.parts.flatMap(p => (p.type === 'text' ? [p.text] : [])).join('\n');
    57	    return (
    58	      <ChatMessage sender="user">
    59	        <ChatMessageBubble variant="filled" xstyle={styles.userText}>
    60	          {text}
    61	        </ChatMessageBubble>
    62	      </ChatMessage>
    63	    );
    64	  }
    65	
    66	  const denied = new Map(message.parts.flatMap(p => (p.type === 'data-denied' ? [[p.data.toolCallId, p.data] as const] : [])));
    67	  const approvals = new Map(message.parts.flatMap(p => (p.type === 'data-approval' ? [[p.data.toolCallId, p.data] as const] : [])));
    68	  // A repair run sends a second verify part; only the latest one is current.
    69	  const lastVerify = message.parts.findLastIndex(p => p.type === 'data-verify');
    70	  // The marker sits between turns, so it renders after everything else in the message.
    71	  const checkpoint = message.parts.findLast(p => p.type === 'data-checkpoint')?.data;
    72	  const toolIds = new Set(message.parts.flatMap(p => (isToolPart(p) ? [p.toolCallId] : [])));
    73	  const label = MODELS.find(m => m.id === message.metadata?.model)?.label;
    74	
    75	  return (
    76	    <ChatMessage
    77	      sender="assistant"
    78	      metadata={
    79	        label && (
    80	          <Text type="supporting" color="secondary">
    81	            {label}
    82	          </Text>
    83	        )
    84	      }>
    85	      {/* Parts are append-only and text parts carry no id, so the index is their stable identity. */}
    86	      {message.parts.map((part, i) => {
    87	        if (part.type === 'text')
    88	          return (
    89	            <Markdown key={`text-${i}`} isStreaming={part.state === 'streaming'}>
    90	              {part.text}
    91	            </Markdown>
    92	          );
    93	        if (part.type === 'reasoning') return <Reasoning key={part.id ?? `reasoning-${i}`} part={part} />;
    94	        if (isToolPart(part)) {
    95	          const deniedCall = denied.get(part.toolCallId);
    96	          if (deniedCall) return <DeniedCall key={part.toolCallId} call={deniedCall} />;
    97	          const approval = approvals.get(part.toolCallId);
    98	          const approvalId = part.approval?.id;
    99	          if (approval && approvalId && part.state !== 'output-available' && part.state !== 'output-error')
   100	            return (
   101	              <ApprovalCard
   102	                key={part.toolCallId}
   103	                approval={approval}
   104	                decision={decisionOf(part)}
   105	                onDecide={approved => onApproval?.(approvalId, approved)}
   106	              />
   107	            );
   108	          return <ToolCall key={part.toolCallId} part={part} />;
   109	        }
   110	        if (part.type === 'data-denied' && !toolIds.has(part.data.toolCallId))
   111	          return <DeniedCall key={`denied-${part.data.toolCallId}`} call={part.data} />;
   112	        if (part.type === 'data-verify')
   113	          return i === lastVerify ? <VerifyResult key={part.id ?? 'verify'} result={part.data} /> : null;
   114	        if (part.type === 'data-diff') return <DiffView key={part.id ?? 'diff'} diff={part.data.diff} />;
   115	        return null;
   116	      })}
   117	      {message.metadata?.notice && (
   118	        <Text type="supporting" color="secondary" display="block">
   119	          {message.metadata.notice}
   120	        </Text>
   121	      )}
   122	      {checkpoint && onEvent && <Checkpoint checkpoint={checkpoint} onEvent={onEvent} />}
   123	    </ChatMessage>
   124	  );
   125	}
