     1	import type {DynamicToolUIPart, ToolUIPart} from 'ai';
     2	import {ChatToolCalls, type ChatToolCallStatus} from '@astryxdesign/core/Chat';
     3	import {VStack} from '@astryxdesign/core/Layout';
     4	import {Text} from '@astryxdesign/core/Text';
     5	import {Code} from './Code';
     6	import {summarizeArgs} from './summarize';
     7	
     8	export type ToolPart = ToolUIPart | DynamicToolUIPart;
     9	
    10	const STATUS: Record<ToolPart['state'], ChatToolCallStatus> = {
    11	  'input-streaming': 'pending',
    12	  'input-available': 'running',
    13	  'approval-requested': 'pending',
    14	  'approval-responded': 'running',
    15	  'output-available': 'complete',
    16	  'output-error': 'error',
    17	  'output-denied': 'error',
    18	};
    19	
    20	const toolName = (part: ToolPart) => (part.type === 'dynamic-tool' ? part.toolName : part.type.slice(5));
    21	
    22	// A single-string result such as {content: '...'} reads better as the string itself.
    23	const unwrap = (value: unknown) => {
    24	  const values = value && typeof value === 'object' ? Object.values(value) : [];
    25	  return values.length === 1 && typeof values[0] === 'string' ? values[0] : value;
    26	};
    27	
    28	function Detail({label, value}: {label: string; value: unknown}) {
    29	  const code = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
    30	  return (
    31	    <VStack gap={1}>
    32	      <Text type="supporting" color="secondary">
    33	        {label}
    34	      </Text>
    35	      <Code code={code} language={typeof value === 'string' ? 'text' : 'json'} />
    36	    </VStack>
    37	  );
    38	}
    39	
    40	export function ToolCall({part}: {part: ToolPart}) {
    41	  const hasInput = part.state !== 'input-streaming';
    42	  return (
    43	    <ChatToolCalls
    44	      calls={[
    45	        {
    46	          key: part.toolCallId,
    47	          name: toolName(part),
    48	          status: STATUS[part.state],
    49	          target: summarizeArgs(part.input),
    50	          errorMessage: part.state === 'output-error' ? part.errorText : undefined,
    51	          resultDetail: hasInput ? (
    52	            <VStack gap={2}>
    53	              <Detail label="Arguments" value={part.input} />
    54	              {part.state === 'output-available' && <Detail label="Result" value={unwrap(part.output)} />}
    55	              {part.state === 'output-error' && <Detail label="Error" value={part.errorText} />}
    56	            </VStack>
    57	          ) : undefined,
    58	        },
    59	      ]}
    60	    />
    61	  );
    62	}
