     9	
    10	const NAMES = {typecheck: 'Typecheck', build: 'Build', runtime: 'Runtime'} as const;
    11	
    12	const ICON = {
    13	  passed: {icon: 'success', color: 'success'},
    14	  failed: {icon: 'error', color: 'error'},
    15	  skipped: {icon: 'info', color: 'tertiary'},
    16	} as const satisfies Record<VerifyCheckStatus, object>;
    17	
    18	const styles = stylex.create({
    19	  root: {
    20	    marginBlockStart: spacingVars['--spacing-2'],
    21	    paddingInline: spacingVars['--spacing-2'],
    22	    borderRadius: radiusVars['--radius-container'],
    23	    backgroundColor: colorVars['--color-background-muted'],
    24	  },
    25	  body: {paddingBlockEnd: spacingVars['--spacing-2']},
    26	});
    27	
    28	const seconds = (ms: number) => `${(ms / 1000).toFixed(1)}s`;
    29	
    30	export function VerifyResult({result}: {result: VerifyResultRecord}) {
    31	  const failed = result.checks.filter(c => c.status === 'failed').map(c => NAMES[c.name]);
    32	  const skipped = result.checks.filter(c => c.status === 'skipped').map(c => NAMES[c.name]);
    33	  const state = !result.ok ? 'failed' : skipped.length ? 'unverified' : 'passed';
    34	  const summary = {passed: 'Checks passed', unverified: `Not verified: ${skipped.join(', ')} check could not run`, failed: `${failed.join(', ')} failed`}[state];
    35	  const icon = {passed: 'success', unverified: 'warning', failed: 'error'} as const;
    36	  return (
    37	    <div {...stylex.props(styles.root)}>
    38	      <Collapsible
    39	        defaultIsOpen={false}
    40	        trigger={
    41	          <HStack gap={2} align="center">
    42	            <Icon icon={icon[state]} size="sm" color={icon[state]} />
    43	            <Text type="supporting">{summary}</Text>
    44	          </HStack>
    45	        }>
    46	        <VStack gap={2} xstyle={styles.body}>
    47	          {result.checks.map(check => (
    48	            <VStack key={check.name} gap={1}>
    49	              <HStack gap={2} align="center">
    50	                <Icon icon={ICON[check.status].icon} size="xsm" color={ICON[check.status].color} />
    51	                <Text type="supporting">{NAMES[check.name]}</Text>
    52	                <Text type="supporting" color="secondary">
    53	                  {check.status === 'skipped' ? 'skipped' : seconds(check.durationMs)}
    54	                </Text>
    55	              </HStack>
    56	              {check.errors.length > 0 && <Code language="text" isWrapped code={check.errors.join("\n")} />}
    57	            </VStack>
    58	          ))}
    59	        </VStack>
    60	      </Collapsible>
    61	    </div>
    62	  );
    63	}
