     4	export const KEY_REJECTED = 'Your API key or sign-in was rejected. Check it and try again.';
     5	export const RATE_LIMITED = 'The model provider is rate limiting requests. Wait a minute and try again.';
     6	export const PROVIDER_FAILED = 'The model provider returned an error. Try again.';
