    12	export const REFUSED = 'The model declined this request. Rephrase it or pick another model.';
    13	// Every cancelled tool call's errorText starts with "Cancelled: ", which is how it is told apart from a tool error.
    14	export const CANCELLED_STOPPED = 'Cancelled: the turn was stopped before this call finished.';
    15	export const CANCELLED_ERROR = 'Cancelled: the turn ended with an error before this call finished.';
    16	export const CANCELLED_STEP_LIMIT = 'Cancelled: the agent hit its step limit before this call ran.';
    17	export const CANCELLED_ENDED = 'Cancelled: the model ended its turn before this call ran.';
    18	export const OUTPUT_LIMIT = 'Output limit reached before this call ran. Continue with one file per step, or use edit_file for targeted edits instead of rewriting whole files.';
    19	export const SANDBOX_FAILED = 'The preview sandbox stopped responding. Reload to try again.';
    20	export const SANDBOX_QUOTA = 'The preview sandbox has used its free monthly quota, so new sandboxes are paused until it resets.';
    21	
    22	const PROVIDER_NAMES: Record<ProviderId, string> = {openai: 'OpenAI', anthropic: 'Anthropic'};
    23	
    24	export const missingKey = ({provider, label}: {provider: ProviderId; label: string}) =>
    25	  `${provider === 'openai' ? 'Sign in or add' : 'Add'} an ${PROVIDER_NAMES[provider]} API key to use ${label}.`;
    26	
    27	// The SDK wraps errors it retried; the provider's status is on the last attempt.
    28	const apiError = (error: unknown) => {
    29	  const last = (error as {lastError?: unknown} | null)?.lastError ?? error;
    30	  return APICallError.isInstance(last) ? last : null;
    31	};
    32	
    33	// Never forward provider text: OpenAI's 401 body echoes part of the key. Anthropic 529 overloaded and 5xx fall through to PROVIDER_FAILED.
    34	export function userMessage(error: unknown): string {
    35	  const status = apiError(error)?.statusCode;
    36	  if (status === 401 || status === 403) return KEY_REJECTED;
    37	  if (status === 429) return RATE_LIMITED;
    38	  return PROVIDER_FAILED;
    39	}
    40	
    41	export function errorStatus(error: unknown): number | string {
    42	  const api = apiError(error);
    43	  return api ? (api.statusCode ?? 'no-status') : error instanceof Error ? error.name : 'unknown';
    44	}
    45	
    46	// Vercel Sandbox answers 402 payment_required once the Hobby quota is used up and creation pauses.
    47	export const sandboxQuotaExceeded = (error: unknown) => (error as {response?: {status?: number}} | null)?.response?.status === 402;
    48	
    49	export const sandboxMessage = (error: unknown) => (sandboxQuotaExceeded(error) ? SANDBOX_QUOTA : SANDBOX_FAILED);

