   140	  const [isConnecting, setIsConnecting] = useState(false);
   141	  const isBusy = isConnecting || status === 'submitted' || status === 'streaming';
   142	  const [view, setView] = useState<View>('chat');
   143	  const [frameKey, setFrameKey] = useState(0);
   144	  const [isFrameLoading, setIsFrameLoading] = useState(true);
   145	  // A server-rendered iframe can finish loading before hydration and its onLoad is lost.
   146	  const isHydrated = useSyncExternalStore(noopSubscribe, () => true, () => false);
