   148	  const send = (text: string, sentModel: string) => {
   149	    if (isBusy) return;
   150	    sendMessage({text, metadata: {model: sentModel}}, {body: {model: sentModel}});
   151	  };
   152	
   153	  const started = useRef(false);
   154	  const firstSendCancelled = useRef(false);
   155	  const stopTurn = () => {
   156	    firstSendCancelled.current = true;
   157	    setIsConnecting(false);
   158	    void stop();
   159	  };
