   238	              <AuthControls />
   239	            </HStack>
   240	          }
   241	        />
   242	      }>
   243	      <div {...stylex.props(styles.body)}>
   244	        <div {...stylex.props(styles.switcher)}>
   245	          <SegmentedControl label="Workspace view" layout="fill" value={view} onChange={v => setView(v as View)}>
   246	            <SegmentedControlItem value="chat" label="Chat" />
