    value?: string;
    /** Called when the input value changes */
    onChange?: (value: string) => void;
    /** Placeholder text for the input */
    placeholder?: string;
    /** Whether the composer is disabled */
    isDisabled?: boolean;
    /** Density variant */
    density?: ChatComposerDensity;
    /**
