    const cards = new Set(m.parts.flatMap(p => (p.type === 'data-approval' ? [p.data.toolCallId] : [])));
    return m.parts.flatMap(p => (isToolPart(p) && p.state === 'approval-requested' && !cards.has(p.toolCallId) ? [p.approval.id] : []));
